            var a = new LwwRegister("tea", 10, "n1");
            var b = new LwwRegister("cake", 10, "n2");
            eq(merge(a, b), b);
            eq(merge(b, a), b);
            eq(merge(a, a), a);
        });
        System.exit(report());
